#!/usr/bin/env bash
set -euo pipefail

# declare associative array
declare -A token_max

# Fill it: token_max["<dataset>,<replication>"]=<value>
# numbers = 4096 * imbalance factor generated by the framework
# dataset: 0->humaneval, 1->gpqa, 2->gsm8k
token_max["0,0"]=7800
token_max["0,16"]=6386
token_max["0,32"]=5766
token_max["0,64"]=5274

token_max["1,0"]=6298
token_max["1,16"]=5356
token_max["1,32"]=5342
token_max["1,64"]=4806

token_max["2,0"]=7128
token_max["2,16"]=5998
token_max["2,32"]=4968
token_max["2,64"]=4930

for dataset in 0 1 2; do
    for routing_scheme in 1 0; do
        for replication in 0 16 32 64; do

            decode_bs=16
            prefill_bs=${token_max["$dataset,$replication"]}

            # decode
            ./bench_serve.sh 8 8 "$replication" "$decode_bs" "$routing_scheme" "$dataset"

            # prefill
            ./bench_serve.sh 8 8 "$replication" "$prefill_bs" "$routing_scheme" "$dataset"

        done
    done
done
